function stepper(labels,current){return `<div class="stepper">${labels.map((l,i)=>`<span class="${i===current?'current':''}">${i+1}. ${l}</span>`).join('')}</div>`}
function expenses(){
  if(state.expenseFlow)return heading('Gider dosyasını içe aktar',button('Listeye dön','expenseExit','','text-button'))+stepper(['Dosya seç','Önizle','Onayla'],state.expenseFlow-1)+`<div class="sheet section-body">${state.expenseFlow===1?`<div class="upload">${icon('upload')}<h2 style="margin-top:15px">Gider tablosunu seçin</h2><p class="muted">Bu prototipte yalnızca sentetik örnek dosya kullanılır.</p>${button('Örnek dosyayı seç','expenseStep','2','primary')}<div style="margin-top:18px">${button('Şablon alanlarını gör','evidence','template','text-button')}</div></div>`:state.expenseFlow===2?`<div class="section-title"><h2>giderler-eylul-ornek.xlsx</h2><span class="tag blue">3 satır · Eylül 2025</span></div>${notice('1 olası tekrar bulundu. İçe aktarmadan önce satır kararını belirtin.')}<div class="table-scroll"><table class="ledger wide-table"><thead><tr><th>Kategori</th><th>Oluşma tarihi</th><th>Tutar</th><th>Karar</th></tr></thead><tbody><tr><td>Kira</td><td>01.09.2025</td><td>20.000,00 ₺</td><td>Yeni kayıt</td></tr><tr><td>İşçilik · aylık toplam</td><td>30.09.2025</td><td>60.000,00 ₺</td><td>Yeni kayıt</td></tr><tr><td>Elektrik</td><td>28.09.2025</td><td>12.000,00 ₺</td><td><select id="duplicate" aria-label="Tekrarlanan satır kararı"><option value="exclude" ${state.duplicate==='exclude'?'selected':''}>Tekrarı dışla</option><option value="include" ${state.duplicate==='include'?'selected':''}>Ayrı gider olarak tut</option></select></td></tr></tbody></table></div><div class="action-row">${button('Geri','expenseStep','1')}${button('Kararları gözden geçir','expenseStep','3','primary')}</div>`:`<h2>İçe aktarma özeti</h2><p>${state.duplicate==='exclude'?'2 kayıt eklenecek. 1 tekrar dışlanacak.':'3 kayıt eklenecek. Olası tekrar ayrı gider olarak tutulacak.'} Etkilenen dönem Eylül 2025.</p>${notice('İçe aktarma, gider tamlığını onaylamaz. Dönemi ayrıca inceleyin.')}<div class="action-row">${button('Vazgeç','expenseExit')}${button('Örnek içe aktarmayı onayla','expenseConfirm','','primary')}</div>`}</div>`;
  return heading('Dönem giderleri',button('Gider dosyası içe aktar','expenseStep','1','primary'))+`<div class="sheet triple"><div><div class="metric-label">Kayıtlı işletme giderleri</div><strong>92.000,00 ₺</strong>${status('expenses','İnceleme gerekli')}</div><div><div class="metric-label">Toplam işçilik</div><strong>60.000,00 ₺</strong>${status('expenses','Aylık toplu kayıt')}</div><div><div class="metric-label">Tamlık durumu</div><strong style="font-size:24px">${state.complete?'Örnek onay verildi':'Onay bekliyor'}</strong>${button('Dönemi incele','completeness','','text-button')}</div></div>${notice('Faaliyet kârı hesaplanamıyor — gider verileri eksik.')}<div class="section-title" style="margin-top:30px"><h2>Gider kayıtları</h2>${button('Gider tamlığını onayla','completeness','','text-button')}</div><div class="sheet table-scroll"><table class="ledger wide-table"><thead><tr><th>Kategori</th><th>Oluşma tarihi</th><th class="num">Tutar</th><th>Durum</th><th></th></tr></thead><tbody>${[['Kira','01.09.2025','20.000,00'],['İşçilik · aylık toplam','30.09.2025','60.000,00'],['Elektrik','28.09.2025','12.000,00']].map((r,i)=>`<tr><td>${button(r[0],'expenseDetail',r[0],'row-link')}</td><td>${r[1]}</td><td class="num">${money(r[2])}</td><td><span class="tag ${i===2?'warn':''}">${i===2?'KDV belirsiz':'İçe aktarıldı'}</span></td><td>${button('İncele','expenseDetail',r[0],'text-button')}</td></tr>`).join('')}</tbody></table></div><div class="footer-note"><span>${state.expenseImported?'Örnek parti G-003 incelendi.':'Parti G-002 · 3 sentetik kayıt'}</span><span>Ödeme tarihi ve sınıflandırma, kayıt ayrıntısında.</span></div>`;
}
function reports(){
  if(state.reportOpen)return overview();
  return heading('Raporlar',button('İki sürümü karşılaştır','compare','','primary'))+`<div class="sheet table-scroll"><table class="ledger wide-table"><thead><tr><th>Seç</th><th>Sürüm · tarih</th><th>Durum</th><th>Veri kesimi</th><th>Değişiklik</th></tr></thead><tbody><tr><td><input type="checkbox" aria-label="v2 sürümünü seç" checked></td><td>${button('v2 · 02.10.2025','openReport','v2','row-link')}</td><td><span class="tag blue">${state.reviewed?'İncelenmiş':'Aday'}</span></td><td>30.09.2025</td><td>2 satış belgesi eklendi</td></tr><tr><td><input type="checkbox" aria-label="v1 sürümünü seç" checked></td><td>${button('v1 · 01.10.2025','openReport','v1','row-link')}</td><td><span class="tag">İncelenmiş</span></td><td>30.09.2025</td><td>İlk kayıt</td></tr></tbody></table></div>${state.compared?`<div class="section-title" style="margin-top:30px"><h2>Değişenler · v1 → v2</h2></div><div class="sheet"><table class="ledger"><thead><tr><th>Ölçüt</th><th class="num">v1</th><th class="num">v2</th></tr></thead><tbody><tr><td>Net satış</td><td class="num">1.243.760,00 ₺</td><td class="num">1.248.560,00 ₺</td></tr><tr><td>Maliyet kapsamı</td><td class="num">%84,6</td><td class="num">%85,0</td></tr><tr><td>Gider tamlığı</td><td class="num">Kanıt eksik</td><td class="num">Kanıt eksik</td></tr></tbody></table>${notice('Tahmini maliyet ve eksik gider kanıtı sürüyor. Kaydetmek, rakamları kesinleştirmez.')}</div><div class="action-row">${button('v2 raporunu aç','openReport','v2')}${button('İncele ve kaydet','reviewReport','','primary')}${button('Excel indir','export','v2')}</div>`:`<div class="section-body"><p class="muted">Bir sürümü açın veya iki sürümün tutar ve kapsam değişikliklerini karşılaştırın.</p></div>`}`;
}
function operations(){return heading('İşlemler',button('Özete dön '+icon('arrow'),'navigate','overview','text-button'))+`<div class="operation-grid"><section class="sheet section-body"><div class="section-title"><h2>Veri paketi</h2><span class="tag blue">Yerel veri</span></div><div class="operation-entry"><div><h3>Veri: ${partial()?'15':'30'}.09.2025</h3><p>Sentetik veri · Örnek paket EM-2025-09</p></div>${button('Kanıt','evidence','dataset','text-button')}</div><div class="operation-entry"><div><h3>Hazırlanmış paketi içe aktar</h3><p>İçe aktarma sırasında mevcut rapor kullanılabilir.</p></div>${button('Veri paketi içe aktar','packagePreview','','primary')}</div><div class="operation-entry"><div><h3>Yedekleme ve kurtarma</h3><p>Yedekleri inceleyin veya geri yüklemeyi önizleyin.</p></div>${button('Aç '+icon('arrow'),'navigate','recovery')}</div></section><section><div class="section-title"><h2>İçe aktarma geçmişi</h2></div><div class="sheet"><table class="ledger"><tbody><tr><td>EM-2025-09<div class="muted small">01.10.2025 · 09:15</div></td><td><span class="tag">Etkinleştirildi</span></td></tr><tr><td>EM-2025-08<div class="muted small">01.10.2025 · 09:08</div></td><td><span class="tag">Tarihsel paket</span></td></tr></tbody></table></div><p class="muted small" style="margin-top:15px">Tarihsel paket etkin veriyi değiştirmedi.</p></section></div>`}
function recovery(){return heading('Yedekleme ve kurtarma',button('İşlemlere dön','navigate','operations','text-button'))+`<div class="operation-grid"><section class="sheet section-body"><div class="section-title"><h2>Yedekleme</h2><span class="tag">Örnek durum</span></div><h3>Son doğrulanmış yedek</h3><p>02.10.2025 · 09:30<br><span class="muted">Veri kesimi 30.09.2025 · 2 rapor sürümü</span></p>${button('Örnek yedek oluştur','backup','','primary')}<div class="operation-entry"><div><h3>Yedek · 02.10.2025</h3><p>Doğrulanmış örnek · 4,8 MB</p></div>${button(state.pinned?'Sabitlendi':'Sabitle','pin')}</div><div class="operation-entry"><div><h3>Yedek · 01.10.2025</h3><p>Doğrulanmış örnek · 4,6 MB</p></div>${button('İçeriği gör','evidence','backup','text-button')}</div>${notice('Yedeği bilgisayardan bağımsız bir yerde, kurtarma anahtarını yedekten ayrı saklayın.')}</section><section class="sheet section-body"><h2>Geri yükleme</h2>${stepper(['Seç','İncele','Onayla'],state.restoreStep)}${state.restoreStep===0?`<p>Yedek dosyasını ve ayrı tuttuğunuz kurtarma anahtarını birlikte seçin.</p><div class="upload">${icon('file')}<p>Prototip yalnızca örnek yedek kullanır.</p>${button('Örnek yedek ve anahtarı seç','restoreStep','1','primary')}</div>`:state.restoreStep===1?`<h3>Yedek içeriği</h3><table class="ledger"><tbody><tr><td>Yedek tarihi</td><td>02.10.2025 · 09:30</td></tr><tr><td>Veri kesimi</td><td>30.09.2025</td></tr><tr><td>Rapor / gider revizyonu</td><td>2 / 3</td></tr></tbody></table><p class="muted">Örnek dosyanın bütünlüğü önizlemede temsil edilir.</p><div class="action-row">${button('Vazgeç','restoreStep','0')}${button('Onaya geç','restoreStep','2','primary')}</div>`:`<h3>Çalışma verileri değiştirilecek</h3><p>Onay, mevcut çalışma verilerini seçilen yedekle değiştirir. Önce mevcut verilerin korunan bir kopyası tutulur.</p>${notice('Kurtarma anahtarını yedekten ayrı saklayın. Bu prototip hiçbir dosyayı değiştirmez.')}<div class="action-row">${button('Vazgeç','restoreStep','0')}${button('Örnek geri yüklemeyi onayla','restoreConfirm','','danger')}</div>`}</section></div>`}
function startup(){const kind=state.scenario;return `<div class="empty"><div class="empty-symbol">${icon(kind==='loading'?'clock':'file')}</div><h1>${kind==='empty'?'Henüz veri yok':kind==='loading'?'Yerel veriler açılıyor':'Yerel veriler açılamadı'}</h1><p class="muted">${kind==='empty'?'Hazırlanmış bir veri paketini içe aktararak satışları ve dönem raporlarını inceleyin.':kind==='loading'?'Yerel kayıtlar hazırlanıyor. Bu ekran açılış durumunun örneğidir.':'Yerel hizmete ulaşılamadı. Yeniden deneyin; sorun sürerse uygulamayı yeniden başlatın.'}</p><div class="row wrap">${kind==='empty'?button('Veri paketi içe aktar','packagePreview','','primary'):button(kind==='loading'?'Örnek açılışı tamamla':'Yeniden dene','reset','','primary')}${button('Yedekten geri yükle','navigate','recovery')}</div>${kind==='empty'?`<div style="margin-top:22px">${button('Giderlere git','navigate','expenses','text-button')}</div>`:''}</div>`}
function evidenceBody(kind){
  if(kind.startsWith('document:')){const record=transactions.find(item=>item.id===kind.slice(9));return `<p>${record.type} · ${record.id}</p><p style="margin-top:16px">Bu belgenin sentetik satırları kendi kaydedilmiş toplamıyla uzlaşıyor. Uyuşmazlık uyarısı başka bir belgeye aittir.</p><dl><div><dt>Belge net toplamı</dt><dd>${money(record.total)}</dd></div><div><dt>Seçili ürün katkısı</dt><dd>${money(record.scope)}</dd></div></dl>`;}

  const bodies={
    dataset:`<p>Bu ekran yalnızca sentetik gösterim verisi kullanır. Gerçek market verisine bağlanmaz.</p><dl><div><dt>Veri kesimi</dt><dd>${partial()?'15':'30'}.09.2025</dd></div><div><dt>Paket hazırlanma</dt><dd>01.10.2025 · 08:45</dd></div><div><dt>İçe aktarma</dt><dd>01.10.2025 · 09:15</dd></div><div><dt>Veri kümesi</dt><dd>demo-em-2025-09</dd></div><div><dt>Bağlantı</dt><dd>Canlı bağlantı kapalı</dd></div></dl>`,
    sales:`<p>İndirim sonrası satışlardan müşteri iadeleri düşülür. Kayıtlı KDV dahil değildir.</p><div class="display-value">${money(net())}</div><span class="tag">${partial()?'Kısmi dönem':'Sentetik kaynakla uzlaşıyor'}</span><dl><div><dt>Satışlar · iade öncesi</dt><dd>${partial()?'630.480,00':state.period==='2025-08'?'1.127.000,00':oldReport()?'1.256.160,00':'1.260.960,00'} ₺</dd></div><div><dt>Müşteri iadeleri</dt><dd>${partial()?'−18.000,00':state.period==='2025-08'?'−7.000,00':'−12.400,00'} ₺</dd></div><div><dt>Dönem</dt><dd>${state.period==='2025-08'?'01–31.08.2025':partial()?'01–15.09.2025':'01–30.09.2025'}</dd></div></dl>${notice('Uzlaşma, yalnızca sentetik örneğin kapsadığı kayıtlar içindir. Gerçek işletme tamlığına kanıt değildir.')}`,
    comparison:`<p>${partial()||state.period==='2025-08'?'Karşılaştırılamıyor. Karşılaştırma için eş kapsamlı bir önceki dönem yok.':oldReport()?'Her iki ay tam dönemdir. v1 farkı +123.760,00 ₺, değişim +%11,05.':'Her iki ay tam takvim dönemi olarak temsil edilir. Net satış farkı +128.560,00 ₺, değişim +%11,48.'}</p><dl><div><dt>Seçili dönem</dt><dd>${state.period==='2025-08'?'01–31.08.2025':partial()?'01–15.09.2025':'01–30.09.2025'}</dd></div><div><dt>Karşılaştırma</dt><dd>${state.period==='2025-08'?'Temmuz verisi yok':'01–31.08.2025'}</dd></div></dl>`,
    count:'<p>Yalnızca tamamlanmış satış belgeleri sayılır. Müşteri iadeleri ve tamamlanmadan iptal edilen belgeler dahil değildir.</p>',
    basket:'<p>İade öncesi net satış tutarı, tamamlanmış satış belgesi sayısına bölünür. İade tutarları ve iade belgeleri ortalamaya dahil değildir.</p><p class="muted" style="margin-top:16px">Görsel tutarlar seçili dönem için önceden hazırlanmıştır.</p>',
    returns:'<p>Müşteri iadeleri net satıştan düşülür. Tedarikçi iadeleri bu nüfusa dahil değildir. İade belgesinde negatif katkı ve kaynak satırı ayrı gösterilir.</p>',
    cost:`<p>Tarihsel son alış maliyeti tahmini. Envanter değerlemesi veya kesin kâr değildir.</p><dl><div><dt>Mutlak satış/iade tutarı kapsamı</dt><dd>%85,0</dd></div><div><dt>Kapsanan net satış</dt><dd>1.061.276,00 ₺</dd></div><div><dt>Tahmini maliyet</dt><dd>812.000,00 ₺</dd></div><div><dt>Kapsanan brüt tahmin</dt><dd>249.276,00 ₺</dd></div><div><dt>Dışlanan net satış</dt><dd>187.284,00 ₺</dd></div><div><dt>Kapsanan / dışlanan satır</dt><dd>8.160 / 1.440</dd></div></dl>${notice('Eksik maliyet sıfır değildir. Vergi temeli, birim veya belge bağlantısı belirsiz satırlar dışlanır.')}<p class="muted small">Kapsam takvim günü oranı değildir. Bu rakamlar standart Eylül senaryosuna ait sabit tasarım örneğidir.</p>`,
    expenses:`<p>Kayıtlı işletme giderleri 92.000,00 ₺. İşçilik 60.000,00 ₺ olarak toplu kayıttır. Sahip katkısı ve finansman hareketleri bu toplama dahil değildir.</p>${notice('Elektrik kaydında KDV işlemi belirsiz. İçe aktarma, dönem giderlerinin tam olduğunu kanıtlamaz.')}`,
    profit:notice('Faaliyet kârı hesaplanamıyor — gider verileri eksik.')+'<p>Gider kayıtlarını, sınıflandırmayı ve dönem tamlığını inceleyin. Sayısal kâr göstermek için gerekli kanıt yoktur.</p>',
    report:'<p>Rapor v2, demo-em-2025-09 veri kümesi ve gider revizyonu 3 ile sabittir. Raporun Geçici durumu ile her ölçütün kanıt durumu ayrıdır.</p><dl><div><dt>Satış hesabı</dt><dd>demo-sales-v1</dd></div><div><dt>Maliyet hesabı</dt><dd>demo-last-purchase-v1</dd></div><div><dt>Rapor sürümü</dt><dd>v2 · Aday</dd></div></dl>',
    discrepancy:`${notice('Örnek kaynak satırında başlık ve satır tutarı uyuşmuyor. Katkı hesaplamadan dışlandı.')}<dl><div><dt>Kaydedilmiş tutar</dt><dd>240,00 ₺</dd></div><div><dt>Doğrulanmış katkı</dt><dd>Hesaplanamıyor</dd></div><div><dt>Dışlanan satır</dt><dd>demo-line-003</dd></div></dl><p>Kaydedilmiş tutar, hesaplanan katkı gibi gösterilmez.</p>`,
    template:'<p>Şablon alanları</p><dl><div><dt>Gerekli</dt><dd>Kayıt kimliği, kategori, oluşma tarihi, tutar, sınıflandırma</dd></div><div><dt>Ayrı tutulur</dt><dd>Ödeme tarihi, KDV işlemi, düzeltme nedeni</dd></div><div><dt>İşçilik</dt><dd>Yalnızca aylık toplam</dd></div></dl><p class="muted">Bu önizleme bir Excel şablonu indirmez.</p>',
    backup:'<dl><div><dt>Yedek</dt><dd>demo-backup-20251002</dd></div><div><dt>Kesim</dt><dd>30.09.2025</dd></div><div><dt>Raporlar</dt><dd>2 sabit sürüm</dd></div><div><dt>Gider revizyonları</dt><dd>3</dd></div></dl><p>Doğrulanmış yedek durumu, yalnızca tasarım örneğidir.</p>'
  };
  if(kind==='sales'&&state.scenario==='discrepancy')return bodies.discrepancy+'<p>Özetteki örnek toplam, uyuşmazlığı bulunan satırın dışlanmasını temsil eder. Etkilenen nüfus için uzlaşma iddiası yapılmaz.</p>';
  if(kind==='cost' && (limited() || state.scenario==='missing'))return notice('Maliyet hesabı için yeterli kanıt yok. Bu durumda bir maliyet veya brüt kâr tutarı gösterilmez.');
  if(kind==='report')return `<p>Rapor ${state.reportOpen?state.selectedVersion:'v2'} · ${state.reportOpen&&state.selectedVersion==='v1'?'İncelenmiş':state.reviewed?'İncelenmiş':'Aday'}. Seçili sürümün tutarı korunur. İnceleme, ölçütlerin güvenini yükseltmez.</p>`;
  return bodies[kind]||bodies.sales;
}
function sourceDetails(){return `<details><summary>Kaynak ve yöntem</summary><dl><div><dt>Veri kümesi / parti</dt><dd>demo-em-2025-09 / demo-batch-01</dd></div><div><dt>Kesim</dt><dd>${partial()?'15':'30'}.09.2025</dd></div><div><dt>Hesap / eşleme</dt><dd>demo-calc-v1 / demo-map-v1</dd></div><div><dt>Uygulama</dt><dd>Throwaway tasarım prototipi</dd></div></dl></details>`}
function drawerContent(){
  const d=state.drawer;
  if(d.type==='evidence')return `<h2 id="drawer-title">${d.value==='dataset'?'Veri durumu':'Bu sayı nasıl oluştu?'}</h2><div style="margin-top:22px">${evidenceBody(d.value)}</div>${sourceDetails()}`;
  if(d.type==='receipt'){
    const t=transactions.find(t=>t.id===d.value);const isReturn=t.type!=='Satış';
    return `<h2 id="drawer-title">${t.type} · ${t.id}</h2><p class="muted" style="margin-top:8px">${t.date}</p>${state.scenario==='discrepancy'&&t.id==='S-025930'?notice('Kanıt eksik · Kaynak satırı uyuşmuyor. Aşağıdaki tutarlar kaydedilmiş belge tutarlarıdır; doğrulanmış katkı değildir.'):''}<h3>Belge net toplamı</h3><div class="display-value ${isReturn?'negative':''}">${money(t.total)}</div>${state.scope?notice(`${state.scenario==='discrepancy'&&t.id==='S-025930'?'Kaydedilmiş seçili kapsam tutarı':'Seçili kapsam katkısı'} ${t.scope} ₺. Tam belge toplamı yukarıda gösterilir.`,true):''}<div class="table-scroll"><table class="ledger"><thead><tr><th>Ürün</th><th>Miktar</th><th class="num">Net</th></tr></thead><tbody><tr><td>${button(state.scope||'Pirinç · 1 kg','sourceLine',t.id,'row-link')}</td><td>${isReturn?'1':{'S-025930':'3','S-025929':'2','S-025925':'4','S-025920':'1'}[t.id]} ${state.scope==='Domates'||state.scope==='Elma'?'kg':'adet'}</td><td class="num">${money(t.scope)}</td></tr>${!isReturn?`<tr><td>Diğer ürünler<div class="small muted">Seçili kapsam dışında</div></td><td>2 adet</td><td class="num">${money({'S-025930':'440,00','S-025929':'260,00','S-025925':'640,00','S-025920':'200,00'}[t.id])}</td></tr>`:''}</tbody></table></div><p class="muted small">Net tutarlar kayıtlı KDV hariçtir. Kaynak satırını ürün adından açın.</p>${sourceDetails()}`;
  }
  if(d.type==='sourceLine'&&state.scenario==='discrepancy'&&d.value==='S-025930')return `<h2 id="drawer-title">Kaynak detayı</h2>${evidenceBody('discrepancy')}${sourceDetails()}<div class="action-row">${button(icon('back')+' Fişe dön','receipt',d.value)}</div>`;
  if(d.type==='sourceLine')return `<h2 id="drawer-title">Kaynak detayı</h2><p style="margin-top:20px">Bu satır, seçili ürünün belgeye yaptığı ${money(transactions.find(t=>t.id===d.value).scope)} net katkıyı temsil eder.</p><span class="tag" style="margin-top:15px">Sentetik kaynakla uzlaşıyor</span>${sourceDetails()}<div class="action-row">${button(icon('back')+' Fişe dön','receipt',d.value)}</div>`;
  if(d.type==='purchaseEvidence')return `<h2 id="drawer-title">${esc(d.value)}</h2><p style="margin-top:20px">Belge ve bağlantıları yalnızca sentetik örnektir.</p>${state.purchaseTab==='returns'?notice(d.value==='Tİ-000018'?'Fiziksel iade tamamlandı. Talep 744,00 ₺. Tanınan alacak ve ödeme durumu bilinmiyor.':'Fiziksel iade tamamlandı. Talep ve tanınan alacak 189,00 ₺. Ödeme durumu bilinmiyor.'):evidenceBody('cost')}<h3>Belge bağlantıları</h3><p>Örnek irsaliye → Örnek fatura. Maliyet nüfusunda tek alış olarak temsil edilir.</p>${sourceDetails()}`;
  if(d.type==='expenseDetail'){const record=d.value==='Kira'?['01.09.2025 / 01.09.2025','20.000,00','1']:d.value==='İşçilik · aylık toplam'?['30.09.2025 / 30.09.2025','60.000,00','2']:['28.09.2025 / 03.10.2025','12.000,00','3'];return `<h2 id="drawer-title">${esc(d.value)}</h2><dl><div><dt>Sınıflandırma</dt><dd>İşletme gideri</dd></div><div><dt>Oluşma / ödeme tarihi</dt><dd>${record[0]}</dd></div><div><dt>KDV işlemi</dt><dd>Bilinmiyor</dd></div><div><dt>Asıl kayıt</dt><dd>G-002 · Satır ${record[2]} · ${record[1]} ₺</dd></div></dl><label>Düzeltilmiş tutar (₺)<input id="correction-amount" value="${record[1]}"></label><label>Düzeltme nedeni<textarea id="correction-reason" placeholder="Neden değiştiğini açıklayın"></textarea></label><p class="muted small">Asıl kayıt ve önceki revizyonlar korunur. Yeni tutar, tamlık incelemesini yeniden gerektirir.</p><div class="action-row">${button('Vazgeç','close')}${button('Düzeltmeyi önizle','correction','','primary')}</div>`;}
  if(d.type==='completeness')return `<h2 id="drawer-title">Gider tamlığını incele</h2><p style="margin-top:20px">Eylül 2025 · 01–30.09.2025 · Gider revizyonu 3</p>${notice('Elektrik kaydının KDV işlemi hâlâ belirsiz. Tamlık onayı bu belirsizliği gidermez.')}<label><span><input type="checkbox" id="complete-check"> Bu döneme ait kayıtların kapsamını inceledim.</span></label><p class="muted small">Bu işlem yalnızca örnek inceleme durumunu değiştirir. Faaliyet kârı belirsizliği devam eder.</p><div class="action-row">${button('Vazgeç','close')}${button('Örnek tamlık onayı ver','complete','','primary')}</div>`;
  if(d.type==='packagePreview')return `<h2 id="drawer-title">Veri paketi içe aktar</h2><p style="margin-top:20px">Örnek paket EM-2025-09 · Kesim 30.09.2025. Bu önizleme bilgisayarınızdaki dosyaları okumaz.</p>${notice('Başarısız bir içe aktarmada son geçerli veri kümesi kullanılmaya devam eder.',true)}<label>Örnek sonuç<select id="import-outcome"><option value="success">Başarılı paket</option><option value="failed">Doğrulama hatası</option><option value="historical">Tarihsel paket</option><option value="unchanged">Değişmeyen paket</option></select></label><div class="action-row">${button('Vazgeç','close')}${button('Örnek içe aktarmayı başlat','startImport','','primary')}</div>`;
  if(d.type==='reviewReport')return `<h2 id="drawer-title">v2 · İncele ve kaydet</h2>${evidenceBody('report')}<label>İnceleme nedeni<textarea id="review-reason" placeholder="Bu sürümü neden kaydettiğinizi yazın"></textarea></label>${notice('Kaydetmek, tahmini maliyeti kesinleştirmez ve gider tamlığını onaylamaz.')}<div class="action-row">${button('Vazgeç','close')}${button('Örnek incelemeyi kaydet','saveReview','','primary')}</div>`;
  if(d.type==='export')return `<h2 id="drawer-title">Excel çıktısı · ${esc(d.value)}</h2><p style="margin-top:20px">Çıktı, seçili sabit sürümü kullanır. Tutarlar ile kesim, yöntem, güven, kapsam ve uyarılar birlikte yer alır.</p><dl><div><dt>Rapor</dt><dd>${esc(d.value)}</dd></div><div><dt>Net satış</dt><dd>${d.value==='v1'?'1.243.760,00':'1.248.560,00'} ₺</dd></div><div><dt>Veri kesimi</dt><dd>30.09.2025</dd></div><div><dt>Gider durumu</dt><dd>Kanıt eksik</dd></div></dl>${notice('Bu tasarım prototipi Excel dosyası üretmez. Bu ekran dışa aktarılacak bağlamın önizlemesidir.',true)}`;
  return '';
}
function renderDrawer(){document.querySelector('.drawer-overlay')?.remove();if(!state.drawer)return;const layer=document.createElement('div');layer.className='drawer-overlay';layer.innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1"><header><span class="muted small">${periodName()} · Sentetik veri</span>${button(icon('close')+' Kapat','close')}</header>${drawerContent()}</section>`;document.body.append(layer);document.getElementById('app').inert=true;layer.querySelector('.drawer').focus();}
function openDrawer(type,value){if(!state.drawer){opener=document.activeElement;listPosition=window.scrollY;}state.drawer={type,value};renderDrawer();}
function closeDrawer(){state.drawer=null;document.querySelector('.drawer-overlay')?.remove();document.getElementById('app').inert=false;opener?.focus();window.scrollTo(0,listPosition);}
function toast(text){state.toast=text;renderToast();}
function renderToast(){document.querySelector('.toast')?.remove();if(!state.toast)return;const t=document.createElement('div');t.className='toast';t.role='status';t.innerHTML=`<span>${esc(state.toast)}</span>${button('Tamam','dismiss')}`;document.body.append(t);}
function switchVariant(direction){const keys=Object.keys(variants);state.variant=keys[(keys.indexOf(state.variant)+direction+3)%3];const url=new URL(location.href);url.searchParams.set('variant',state.variant);history.replaceState(null,'',url);render();}
function render(){
  document.body.className=`variant-${state.variant}`;
  const start=['empty','failure','loading'].includes(state.scenario)&&!['operations','recovery','expenses'].includes(state.page);
  const body=start?startup():limited()&&['purchasing','expenses','reports'].includes(state.page)&&!state.reportOpen?heading(names[state.page])+detailUnavailable():({overview,sales,purchasing,expenses,reports,operations,recovery}[state.page])();
  const job=state.job?`<div class="job" role="status"><span>${state.job.label} · ${state.job.progress}%</span><progress value="${state.job.progress}" max="100" aria-label="İşlem ilerlemesi"></progress>${button('İptal et','cancelJob')}</div>`:'';
  document.getElementById('app').innerHTML=shell()+job+`<main class="workspace" id="main">${state.importError?`<div style="margin-bottom:22px">${notice('İçe aktarma tamamlanamadı. Henüz etkin veri yok. Hazırlanmış paketi yeniden seçin.')}</div>`:''}${state.scenario==='importFailure'?`<div style="margin-bottom:22px">${notice('İçe aktarma tamamlanamadı. Son geçerli veriler korundu. '+button('Yeniden dene','packagePreview','','text-button'))}</div>`:''}${body}<div class="state-code">Prototip · ${variants[state.variant]} · ${names[state.page]}${state.page==='sales'?' / '+({overview:'Genel bakış',categories:'Kategoriler',products:'Ürünler',transactions:'İşlemler'}[state.sub]):''} · ${scenarios[state.scenario]} · ${state.page==='sales'&&state.scope?esc(state.scope):'Tüm kapsam'} · İşlemler yalnızca örnektir.</div></main><div class="prototype-bar" aria-label="Prototip denetimleri">${button(icon('back'),'variantPrevious')}<div><strong>${state.variant} · ${variants[state.variant]}</strong><span class="bar-caption">TASARIM PROTOTİPİ · ← → ile değiştir</span></div>${button(icon('arrow'),'variantNext')}<div class="prototype-state"><select id="scenario" aria-label="Örnek veri durumu">${Object.entries(scenarios).map(([k,l])=>`<option value="${k}" ${state.scenario===k?'selected':''}>${l}</option>`).join('')}</select></div></div>`;
  document.querySelector('[data-action="variantPrevious"]').ariaLabel='Önceki tasarım';document.querySelector('[data-action="variantNext"]').ariaLabel='Sonraki tasarım';
  renderToast();
}
function navigate(page){state.page=page;state.toast='';state.reportOpen=false;state.query='';render();window.scrollTo(0,0);}
function startJob(kind,outcome='success'){
  closeDrawer();clearInterval(jobTimer);state.job={label:kind==='backup'?'Örnek yedek doğrulanıyor':'Örnek paket denetleniyor',progress:10};render();
  jobTimer=setInterval(()=>{state.job.progress+=30;if(state.job.progress>=100){clearInterval(jobTimer);state.job=null;if(kind==='backup')toast('Örnek yedek oluşturma ve doğrulama tamamlandı. Gerçek yedek yazılmadı.');else if(outcome==='failed'){if(state.scenario==='empty'){state.importError=true;toast('Paket doğrulanamadı. Henüz etkin veri yok.');}else{state.scenario='importFailure';toast('Paket doğrulanamadı. Son geçerli veriler korundu.');}}else{if(state.scenario==='empty'&&outcome==='success'){state.scenario='normal';state.importError=false;}toast(outcome==='historical'?'Tarihsel paket. Etkin veriler değiştirilmedi.':outcome==='unchanged'?'Paket zaten etkin. Veriler değiştirilmedi.':'Örnek içe aktarma tamamlandı. Gerçek veri değiştirilmedi.');}}render();},1100);
}
document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;const value=el.dataset.value;
  if(action==='navigate'){navigate(value);return;}
  if(['evidence','receipt','sourceLine','purchaseEvidence','expenseDetail','completeness','packagePreview','reviewReport','export'].includes(action)){openDrawer(action,value);return;}
  if(action==='close'){closeDrawer();return;}
  if(action==='dismiss'){state.toast='';renderToast();return;}
  if(action==='variantPrevious'||action==='variantNext'){switchVariant(action==='variantNext'?1:-1);return;}
  if(action==='salesOverview'){state.sub='overview';navigate('sales');return;}
  if(action==='salesTab'){state.sub=value;state.query='';render();return;}
  if(action==='categories'){state.sub='categories';state.scope='';navigate('sales');return;}
  if(action==='category'){state.scope=value;state.sub='products';navigate('sales');return;}
  if(action==='product'){state.scope=value;state.sub='transactions';navigate('sales');return;}
  if(action==='products'){state.sub='products';state.scope='Temel gıda';navigate('sales');return;}
  if(action==='transactions'){state.sub='transactions';state.scope='';navigate('sales');return;}
  if(action==='clearScope'){state.scope='';render();return;}
  if(action==='filter'){state.filter=value;render();return;}
  if(action==='purchaseTab'){state.purchaseTab=value;render();return;}
  if(action==='expenseStep'){state.expenseFlow=Number(value);render();return;}
  if(action==='expenseExit'){state.expenseFlow=0;render();return;}
  if(action==='expenseConfirm'){state.expenseFlow=0;state.expenseImported=true;render();toast('Örnek parti G-003 incelendi. Tamlık onayı verilmedi; gerçek kayıt eklenmedi.');return;}
  if(action==='correction'){const reason=document.getElementById('correction-reason');if(!reason.value.trim()){reason.setCustomValidity('Düzeltme nedenini yazın.');reason.reportValidity();reason.oninput=()=>reason.setCustomValidity('');return;}closeDrawer();toast('Düzeltme önizlendi. Asıl kayıt korunur; prototip gerçek kayıt değiştirmez.');return;}
  if(action==='complete'){if(!document.getElementById('complete-check').checked){toast('Önce dönem kapsamını incelediğinizi işaretleyin.');return;}state.complete=true;closeDrawer();render();toast('Örnek tamlık incelemesi kaydedildi. KDV belirsizliği sürüyor.');return;}
  if(action==='compare'){if(document.querySelectorAll('input[type="checkbox"]:checked').length!==2){toast('Karşılaştırmak için iki sürüm seçin.');return;}state.compared=true;render();return;}
  if(action==='openReport'){state.reportOpen=true;state.selectedVersion=value;render();window.scrollTo(0,0);return;}
  if(action==='reportBack'){state.reportOpen=false;render();return;}
  if(action==='saveReview'){const reason=document.getElementById('review-reason');if(!reason.value.trim()){reason.setCustomValidity('İnceleme nedenini yazın.');reason.reportValidity();reason.oninput=()=>reason.setCustomValidity('');return;}state.reviewed=true;closeDrawer();render();toast('Örnek v2 incelemesi kaydedildi. Ölçütlerin kanıt durumu değişmedi.');return;}
  if(action==='startImport'){startJob('import',document.getElementById('import-outcome').value);return;}
  if(action==='backup'){startJob('backup');return;}
  if(action==='cancelJob'){clearInterval(jobTimer);state.job=null;render();toast('Örnek işlem iptal edildi. Mevcut veriler korundu.');return;}
  if(action==='restoreStep'){state.restoreStep=Number(value);render();return;}
  if(action==='restoreConfirm'){state.restoreStep=0;render();toast('Geri yükleme akışı tamamlandı. Prototip hiçbir çalışma verisini değiştirmedi.');return;}
  if(action==='pin'){state.pinned=!state.pinned;render();return;}
  if(action==='reset'){state.scenario='normal';render();}
});
document.addEventListener('change',event=>{
  if(event.target.id==='period'){state.period=event.target.value;state.scope='';state.sub='overview';state.reportOpen=false;state.toast='';render();}
  if(event.target.id==='scenario'){state.scenario=event.target.value;state.importError=false;state.complete=false;state.page='overview';state.period='2025-09';state.reportOpen=false;state.toast='';render();}
  if(event.target.id==='duplicate')state.duplicate=event.target.value;
  if(event.target.id==='comparison')document.getElementById('comparison-copy').textContent=event.target.value==='Önceki yıl'?'Karşılaştırılamıyor. Eylül 2024 bu örnek pakette yok.':'01–30.09.2025 / 01–31.08.2025 · +%11,48';
  if(event.target.id==='supplier')filterPurchases();
});
function filterPurchases(){const query=document.getElementById('purchase-search').value.toLocaleLowerCase('tr');const supplier=document.getElementById('supplier').value;let visible=0;document.querySelectorAll('#purchase-table tbody tr').forEach(row=>{const matches=row.textContent.toLocaleLowerCase('tr').includes(query)&&(supplier==='Tüm tedarikçiler'||row.dataset.supplier===supplier);row.hidden=!matches;if(matches)visible++;});document.getElementById('purchase-empty').classList.toggle('hidden',visible>0);}
document.addEventListener('input',event=>{if(event.target.id==='search'){const position=event.target.selectionStart;state.query=event.target.value;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(position,position);}if(event.target.id==='purchase-search')filterPurchases();});
document.addEventListener('keydown',event=>{
  if(state.drawer){if(event.key==='Escape'){event.preventDefault();closeDrawer();}if(event.key==='Tab'){const items=[...document.querySelector('.drawer').querySelectorAll('button, input, select, textarea, summary')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('drawer'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}
  if(event.target.closest('input,textarea,select,[contenteditable="true"]'))return;
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();switchVariant(event.key==='ArrowRight'?1:-1);}
});
render();
